final class SendTests: XCTestCase {
    func testSendBenchmarkTest() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let room = app.cells.containing(.staticText, identifier: "Weekend Plans").firstMatch
        let foundRoom = room.waitForExistence(timeout: 20)
        print("ROOM_FOUND=\(foundRoom)")
        guard foundRoom else {
            print("HIERARCHY_HOME:\n" + app.debugDescription)
            return
        }
        room.tap()

        let composer = app.textViews.firstMatch
        let foundComposer = composer.waitForExistence(timeout: 20)
        print("COMPOSER_FOUND=\(foundComposer)")
        print("HIERARCHY_ROOM:\n" + app.debugDescription)
        guard foundComposer else { return }

        composer.tap()
        composer.typeText("benchmark test")
        Thread.sleep(forTimeInterval: 1)
        print("HIERARCHY_TYPED:\n" + app.debugDescription)
    }
}

