import XCTest

final class SendTests: XCTestCase {
    func testSendBenchmarkTest() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let composer = app.textViews["GrowingTextView"]
        if !composer.waitForExistence(timeout: 3) {
            let room = app.cells.containing(.staticText, identifier: "Weekend Plans").firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 20), "room not found:\n" + app.debugDescription)
            room.tap()
            XCTAssertTrue(composer.waitForExistence(timeout: 20), "composer not found:\n" + app.debugDescription)
        }

        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 2) {
            gotIt.tap()
        }

        composer.tap()
        composer.typeText("benchmark test")

        let send = app.buttons["SendButton"]
        XCTAssertTrue(send.waitForExistence(timeout: 10), "send button not found:\n" + app.debugDescription)
        let enabled = NSPredicate(format: "isEnabled == true")
        expectation(for: enabled, evaluatedWith: send)
        waitForExpectations(timeout: 10)
        send.tap()
        Thread.sleep(forTimeInterval: 2)
    }
}
